#!/usr/bin/env node
// Generate offline, reproducible notices from the pinned sources and Cargo.lock.
// Fetch missing locked crates explicitly before running this script; it never
// downloads packages, compiles code, or changes files other than its output.
import { createHash } from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const output = path.join(root, "THIRD-PARTY-NOTICES");
const check = process.argv.includes("--check");
if (process.argv.slice(2).some((arg) => arg !== "--check")) {
  throw new Error("Usage: node scripts/third-party-notices.mjs [--check]");
}
const read = (file) => fs.readFileSync(file, "utf8");
const hash = (text) => createHash("sha256").update(text).digest("hex");
const quote = (text) => JSON.parse(text);
const field = (toml, key) => {
  const match = new RegExp(`^${key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*=\\s*("(?:[^"\\\\]|\\\\.)*")\\s*$`, "m").exec(toml);
  return match ? quote(match[1]) : null;
};
const lock = read(path.join(root, "Cargo.lock"));
const packages = lock.split(/^\[\[package\]\]\s*$/m).slice(1).map((entry) => ({
  name: field(entry, "name"), version: field(entry, "version"), source: field(entry, "source"),
}));
if (!packages.length || packages.some((p) => !p.name || !p.version)) throw new Error("Cannot parse Cargo.lock package entries");
const upstream = JSON.parse(read(path.join(root, "upstream.json")));
const tsrs = path.join(root, ".repos/tsrs");
const typescript = read(path.join(tsrs, "Cargo.toml")).split("[workspace.metadata.typescript]")[1]?.split(/^\[/m)[0];
if (!typescript || !field(typescript, "commit")) throw new Error("Missing pinned TypeScript provenance");
const toolchain = field(read(path.join(root, "rust-toolchain.toml")), "channel");
if (!toolchain) throw new Error("Missing Rust toolchain pin");
const cargoHome = process.env.CARGO_HOME || path.join(os.homedir(), ".cargo");
const registryRoot = path.join(cargoHome, "registry/src");
const registries = fs.existsSync(registryRoot) ? fs.readdirSync(registryRoot).sort().map((name) => path.join(registryRoot, name)) : [];
const sources = [];
const documents = new Map();
function addText(label, text) {
  if (!text.trim()) throw new Error(`Empty license source: ${label}`);
  const id = hash(text);
  if (!documents.has(id)) documents.set(id, { text, labels: [] });
  documents.get(id).labels.push(label);
  return id;
}
function addFile(label, file) { return addText(label, read(file)); }
function source(name, license, files, extra = "") {
  const ids = files.map(([label, file]) => addFile(label, file));
  sources.push({ name, license, ids: [...new Set(ids)], extra });
}
source("Effect diagnostic port", "MIT", [["effect-tsrs/LICENSE (retained effect-tsgo license)", path.join(root, "LICENSE")]],
  "Derived from https://github.com/Effect-TS/tsgo at 8813161074039b67ddb8fe1847e8efa0d8ff1e24.");

source("tsrs and TypeScript-derived compiler / bundled lib.*.d.ts", "Apache-2.0; third-party terms retained in NOTICE", [
  ["tsrs/LICENSE", path.join(tsrs, "LICENSE")],
  ["tsrs/NOTICE", path.join(tsrs, "NOTICE")],
  ["tsrs/licenses/Go-LICENSE", path.join(tsrs, "licenses/Go-LICENSE")],
], `tsrs: ${upstream.repository} at ${upstream.revision}.\nTypeScript: https://github.com/microsoft/TypeScript at ${field(typescript, "commit")} (${field(typescript, "version")}).\nLocally modified compiler files are recorded in patches/checker-extensions.patch.\nCrates: ${packages.filter((p) => !p.source && p.name.startsWith("tsrs_")).map((p) => `${p.name} ${p.version}`).sort().join(", ")}.`);

for (const pkg of packages.filter((p) => p.source).sort((a, b) => a.name.localeCompare(b.name, "en") || a.version.localeCompare(b.version, "en"))) {
  if (!pkg.source.startsWith("registry+")) throw new Error(`Unhandled dependency source: ${pkg.name}: ${pkg.source}`);
  const directory = registries.map((r) => path.join(r, `${pkg.name}-${pkg.version}`)).find((p) => fs.existsSync(path.join(p, "Cargo.toml")));
  if (!directory) throw new Error(`Missing locked source ${pkg.name} ${pkg.version}; run cargo fetch --locked before generating notices`);
  const manifest = read(path.join(directory, "Cargo.toml"));
  const section = manifest.split(/^\[package\]\s*$/m)[1]?.split(/^\[/m)[0] || "";
  const license = field(section, "license");
  const licenseFile = field(section, "license-file");
  if (!license && !licenseFile) throw new Error(`No license declaration: ${pkg.name}`);
  const names = fs.readdirSync(directory).filter((name) => /^(?:licen[cs]e|copying|copyright|notice|unlicense)(?:$|[-_.])/i.test(name) && fs.statSync(path.join(directory, name)).isFile()).sort();
  if (licenseFile && !names.includes(licenseFile)) names.push(licenseFile);
  if (pkg.name === "libmimalloc-sys2") names.push("c_src/mimalloc/LICENSE", "c_src/mimalloc3/LICENSE");
  if (!names.length) throw new Error(`No license/notice files found: ${pkg.name}`);
  source(`${pkg.name} ${pkg.version}`, license || `See ${licenseFile}`, names.map((name) => [`${pkg.name}-${pkg.version}/${name}`, path.join(directory, name)]),
    `https://crates.io/crates/${pkg.name}/${pkg.version}${field(section, "repository") ? `\nUpstream: ${field(section, "repository")}` : ""}`);
}
for (const pkg of packages.filter((p) => !p.source && p.name !== "effect-tsrs" && !p.name.startsWith("tsrs_"))) {
  throw new Error(`Unhandled local dependency: ${pkg.name} ${pkg.version}`);
}

// The standard library is linked into the binary independently of Cargo.lock.
// Preserve the toolchain's full dependency notice set (a conservative superset
// across targets), deduplicating only exactly identical license text.
let sysroot = process.env.RUST_SYSROOT;
if (!sysroot) {
  const result = spawnSync("rustup", ["which", "--toolchain", toolchain, "rustc"], { encoding: "utf8" });
  if (result.status !== 0) throw new Error(`Cannot locate Rust ${toolchain}: ${result.stderr}`);
  sysroot = path.dirname(path.dirname(result.stdout.trim()));
}
const rustDocs = path.join(sysroot, "share/doc/rust");
const rustCopyright = read(path.join(rustDocs, "COPYRIGHT-library.html"));
function decodeHtml(text) {
  return text.replace(/&#(x[0-9a-f]+|[0-9]+);/gi, (_, code) => String.fromCodePoint(code[0].toLowerCase() === "x" ? parseInt(code.slice(1), 16) : Number(code)))
    .replace(/&(?:amp|lt|gt|quot|apos|nbsp);/g, (entity) => ({ "&amp;": "&", "&lt;": "<", "&gt;": ">", "&quot;": '"', "&apos;": "'", "&nbsp;": "\u00a0" })[entity]);
}
function plainHtml(text) {
  return decodeHtml(text.replace(/<[^>]*>/g, "")).split("\n").map((line) => line.trim()).filter(Boolean).join("\n");
}
const rustInTree = rustCopyright.split('<h2 id="out-of-tree-dependencies">')[0].split("<body>")[1];
if (!rustInTree) throw new Error("Unrecognized Rust standard-library copyright format");
sources.push({ name: `Rust ${toolchain} standard library: in-tree sources`, license: "Apache-2.0 OR MIT, with listed exceptions", ids: [
  addText(`Rust ${toolchain} COPYRIGHT-library.html / in-tree attribution`, plainHtml(rustInTree)),
  addFile(`Rust ${toolchain} licenses/Apache-2.0.txt`, path.join(rustDocs, "licenses/Apache-2.0.txt")),
  addFile(`Rust ${toolchain} licenses/MIT.txt`, path.join(rustDocs, "licenses/MIT.txt")),
  addFile(`Rust ${toolchain} licenses/Unicode-3.0.txt`, path.join(rustDocs, "licenses/Unicode-3.0.txt")),
  addFile(`Rust ${toolchain} licenses/BSD-2-Clause.txt`, path.join(rustDocs, "licenses/BSD-2-Clause.txt")),
], extra: `https://github.com/rust-lang/rust/releases/tag/${toolchain}\nAttributions and license texts below are extracted from the pinned toolchain's COPYRIGHT-library.html and licenses directory.` });
let rustDependencyCount = 0;
for (const section of rustCopyright.split("<h3>").slice(1)) {
  const end = section.indexOf("</h3>");
  if (end < 0) throw new Error("Unrecognized Rust dependency heading");
  const name = plainHtml(section.slice(0, end)).replace(/^📦\s*/, "");
  // These components are exclusive to targets not published by effect-tsrs.
  if (/^(?:fortanix-sgx-abi|vex-sdk|wasi(?:p[123])?|wasm(?:parser|printer|-(?:encoder|metadata))|wit-(?:bindgen|component|parser))(?:-|$)/.test(name)) continue;
  const license = /<b>License:<\/b>\s*([^<]+)<\/p>/.exec(section)?.[1];
  const texts = [...section.matchAll(/<summary><code>([^<]+)<\/code><\/summary>\s*<pre>([\s\S]*?)<\/pre>/g)];
  if (!license || !texts.length) throw new Error(`Missing Rust toolchain dependency notices: ${name}`);
  sources.push({ name: `Rust ${toolchain} standard-library dependency: ${name}`, license: decodeHtml(license),
    ids: [...new Set(texts.map((m) => addText(`Rust ${toolchain} COPYRIGHT-library.html / ${name}/${decodeHtml(m[1])}`, decodeHtml(m[2]).replace(/^\n/, "").replace(/\n[ \t]*$/, ""))))], extra: "" });
  rustDependencyCount++;
}
if (!rustDependencyCount) throw new Error("No Rust standard-library dependency notices found");
