if (toolchain !== "1.99.1") throw new Error("Refresh embedded native notices for the changed Rust toolchain");
for (const native of nativeNotices) {
  if (hash(native.text) !== native.sha256) throw new Error(`Native notice checksum mismatch: ${native.label}`);
  const id = addText(native.label, native.text);
  sources.push({ name: native.name, license: native.license, ids: [id], extra: native.url });
}

source("Patched Oxlint frontend bindings, schema and presets", "MIT", [
  ["Oxlint/LICENSE", path.join(root, "licenses/oxlint/LICENSE")],
  ["Effect-TS/tsgo/LICENSE", path.join(root, "LICENSE")],
], "Oxlint 1.87.0, 1.88.0 and 1.89.0 from https://github.com/oxc-project/oxc.\nEffect plugin bindings, schema and presets redistributed from @effect/tsgo@0.56.1 (https://github.com/Effect-TS/tsgo).\nOnly frontend bindings are bundled; the generic tsgolint backend is supplied by the consuming project's oxlint-tsgolint installation.");

const ids = new Map([...documents.keys()].map((id, i) => [id, `N${String(i + 1).padStart(3, "0")}`]));
let result = `THIRD-PARTY NOTICES FOR EFFECT-TSRS\n\nGenerated by scripts/third-party-notices.mjs from pinned local source files.\nCargo.lock SHA-256: ${hash(lock)}\n\nThis file accompanies the compiled effect-tsrs binary. It retains upstream\nlicense terms, copyright notices, and attribution notices. It does not alter\nthose terms. License expressions below are the upstream declarations.\n\nCoverage includes every package in Cargo.lock, including build-time and\nplatform-specific packages, plus the pinned native runtimes and Rust standard library's published\nthird-party notice set, excluding SGX/VEX/WebAssembly-only components.
This conservative superset covers npm binaries for:\n  aarch64-apple-darwin\n  x86_64-apple-darwin\n  aarch64-unknown-linux-musl\n  x86_64-unknown-linux-musl\n  x86_64-pc-windows-msvc\nNot every listed dependency is linked into every platform binary.\n\nThe Effect implementation's own MIT license is also distributed as LICENSE.\nUpstream notices are reproduced below without rewriting their license or\ncopyright text; repeated identical source files share one notice entry.\n\nCOMPONENT INDEX\n===============\n`;
for (const s of sources) {
  result += `\n${s.name}\nDeclared license: ${s.license}\nNotices: ${s.ids.map((id) => ids.get(id)).join(", ")}\n`;
  if (s.extra) result += `${s.extra}\n`;
}
result += "\n\nLICENSE AND ATTRIBUTION TEXTS\n=============================\n";
for (const [id, document] of documents) {
  result += `\n\n----- ${ids.get(id)} -----\nSources:\n${document.labels.map((label) => `  ${label}`).join("\n")}\nSHA-256 of source text: ${id}\n----- BEGIN UPSTREAM TEXT -----\n${document.text}${document.text.endsWith("\n") ? "" : "\n"}----- END UPSTREAM TEXT -----\n`;
}
if (check) {
  if (!fs.existsSync(output) || read(output) !== result) throw new Error("THIRD-PARTY-NOTICES is stale; regenerate with node scripts/third-party-notices.mjs");
  console.log(`THIRD-PARTY-NOTICES verified: ${sources.length} components, ${documents.size} distinct notice texts`);
} else {
  fs.writeFileSync(output, result);
  console.log(`Generated THIRD-PARTY-NOTICES: ${sources.length} components, ${documents.size} distinct notice texts, ${Buffer.byteLength(result)} bytes`);
}
